{"sql":"-- Enable RLS on all five tables
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;"}

{"sql":"-- Fix the delete policy using correct column name 'user_id' for the moderator in channel_moderators
DROP POLICY IF EXISTS delete_channel_moderators_owner_or_self ON public.channel_moderators;
CREATE POLICY delete_channel_moderators_owner_or_self ON public.channel_moderators
FOR DELETE
USING (is_channel_owner(channel_id, app_current_user_id()) OR user_id = app_current_user_id());"}
